def _cli_name(name: str) -> int:
    if len(name) == 0:
        return 0
    for i in range(len(name)):
        c = ord(name[i])
        letter = c >= 65 and c <= 90 or (c >= 97 and c <= 122)
        if not letter and (i == 0 or not (c >= 48 and c <= 57 or c == 95 or c == 45)):
            return 0
    return 1

def cli_parse(args: list[str], value_options: list[str], switch_options: list[str]) -> CliArgs:
    kinds: dict[str, str] = {}
    for name in value_options:
        if not _cli_name(name) or name in kinds:
            raise ValueError
        kinds[name] = 'value'
    for name in switch_options:
        if not _cli_name(name) or name in kinds:
            raise ValueError
        kinds[name] = 'switch'
    options: dict[str, str] = {}
