    i = 0
    while i < len(args):
        token = args[i]
        i += 1
        if ended or not token.startswith('--'):
            positional.append(token)
        elif token == '--':
            ended = 1
        else:
            body = token[2:]
            separator = body.find('=')
            name = body
            if separator >= 0:
                name = body[:separator]
            if name not in kinds or name in options:
                raise ValueError
            value = ''
            if kinds[name] == 'switch':
                if separator >= 0:
                    raise ValueError
            elif separator >= 0:
                value = body[separator + 1:]
            else:
                if i >= len(args):
                    raise ValueError
                value = args[i]
                if value.startswith('--'):
                    raise ValueError
                i += 1
            options[name] = value
    return CliArgs(options, positional)
